-- 0111: Seed the Edappadi (Poolavari) DTCP layout.
--
-- Data only — no schema change. The geometry blob and the 27 plot rows are
-- generated by scripts/extract-dtcp-layout.py straight from the sanctioned
-- approval drawing (application LP/EDP/2026/0148), so this seed can always be
-- re-derived from, and diffed against, the legal sheet.
--
-- `geometry` carries only the plan chrome (boundary, OSR, roads, dimensions,
-- area statement, notes). The plots themselves live in layout_plots so there is
-- exactly one source of truth for plot state.
--
-- Commercial fields are deliberately left NULL: no price appears anywhere on
-- the DTCP drawing, so the admin sets them in Admin -> Plot layouts before the
-- layout is published. `is_published` starts false for the same reason.

with g as (select '{"slug":"edappadi-poolavari","authority":"Directorate of Town and Country Planning","title":"Layout Plan — Residential Subdivision","place":"Edappadi Town Panchayat · Salem District · Tamil Nadu","approvalNo":"LP/EDP/2026/0148","approvalDate":"2026-07-30","owner":"Thiru. A. Selvaraj","surveyNos":"214/1B, 214/2, 215/1","village":"Poolavari","taluk":"Edappadi","district":"Salem","scale":"1:1000","viewBox":[30,100,300,540],"boundary":[[150.21,133.03],[284.25,139.73],[293.19,267.07],[296.54,355.32],[206.06,359.78],[181.48,569.79],[83.19,577.6]],"osr":{"rect":[206.06,296.11,306.59,363.14],"areaSqm":1342.0,"label":"O.S.R."},"existingRoad":{"quad":[[44.09,588.77],[49.67,615.58],[212.76,598.83],[207.18,572.02]],"label":"EXISTING ROAD — 12.00 m WIDE","widthM":12.0},"roads":[{"label":"9.00 m ROAD","widthM":9.0,"band":[141.83,182.18,293.74,201.17]},{"label":"9.00 m ROAD","widthM":9.0,"band":[127.87,279.36,293.74,297.23]},{"label":"12.00 m ROAD","widthM":12.0,"band":[152.44,359.78,206.06,569.79],"rotate":-84}],"dimensions":[{"label":"72.40 m","from":[150.21,121.86],"to":[284.25,128.56]},{"label":"118.60 m","from":[307.71,144.2],"to":[307.71,356.43]},{"label":"246.15 m","from":[69.78,138.61],"to":[60.85,574.25]}],"areaStatement":[{"label":"Total extent of site","areaSqm":13420.0,"percent":100.0},{"label":"Area under roads","areaSqm":3218.0,"percent":24.0},{"label":"Open space reservation","areaSqm":1342.0,"percent":10.0},{"label":"Saleable plot area","areaSqm":8860.0,"percent":66.0}],"totalPlots":27,"notes":["All dimensions are in metres; areas in square metres.","Roads shall be formed to the full width shown and handed over to the local body free of cost.","The open space reservation is transferred to the local body by registered gift deed.","Ten per cent of the total extent is reserved as open space as required.","No plot shall be subdivided further without prior sanction.","Building setbacks shall follow the development regulations in force.","Water supply, storm-water drains and street lighting are provided by the promoter.","Electricity supply lines shall be laid along the road margin.","This approval does not confer title to the land."],"amenities":[{"kind":"osr","label":"Open Space Reservation","icon":"leaf","at":[256.3,329.6]},{"kind":"entrance","label":"Entrance from existing road","icon":"enter","at":[167.0,566.0]}]}'::jsonb as j)
insert into public.layouts (
  slug, name, authority, title, place, approval_no, approval_date,
  owner_name, survey_nos, village, taluk, district, scale, geometry, amenities, is_published
)
select
  'edappadi-poolavari',
  'Edappadi — Poolavari Layout',
  'Directorate of Town and Country Planning',
  'Layout Plan — Residential Subdivision',
  'Edappadi Town Panchayat · Salem District · Tamil Nadu',
  'LP/EDP/2026/0148',
  date '2026-07-30',
  'Thiru. A. Selvaraj',
  '214/1B, 214/2, 215/1',
  'Poolavari', 'Edappadi', 'Salem', '1:1000',
  g.j, g.j -> 'amenities', false
from g
on conflict (slug) do update set
  geometry      = excluded.geometry,
  amenities     = excluded.amenities,
  authority     = excluded.authority,
  title         = excluded.title,
  place         = excluded.place,
  approval_no   = excluded.approval_no,
  approval_date = excluded.approval_date,
  owner_name    = excluded.owner_name,
  survey_nos    = excluded.survey_nos,
  village       = excluded.village,
  taluk         = excluded.taluk,
  district      = excluded.district,
  scale         = excluded.scale;

-- Plots. Sizes and areas come from the plot schedule on sheet 2; `rect` is the
-- traced outline used for display only. Re-running refreshes the sanctioned
-- geometry without touching status, pricing or ownership.
insert into public.layout_plots (layout_id, number, block, rect, width_m, depth_m, area_sqm, facing, road_width_m)
select l.id, v.number, v.block, v.rect, v.width_m, v.depth_m, v.area_sqm, v.facing,
       case when v.block in ('A','B','C','D') then 9.00 else 12.00 end
